<?php require '_auth.php';if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("UPDATE orders SET status=? WHERE id=?")->execute([$_POST['status'],(int)$_POST['id']]);}$adminTitle='Orders';$orders=$pdo->query("SELECT * FROM orders ORDER BY id DESC")->fetchAll();include '_header.php';?><section class="panel"><div class="panel-head"><h2>Order management</h2></div><table class="table"><tr><th>ID</th><th>Customer</th><th>Phone</th><th>Total</th><th>Status</th><th>Update</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['customer_name'])?><br><small><?=e($o['email'])?></small></td><td><?=e($o['phone'])?></td><td>LKR <?=number_format($o['total'],2)?></td><td><span class="status"><?=e($o['status'])?></span></td><td><form method="post" style="display:flex;gap:7px"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach(['Pending','Confirmed','Packed','Shipped','Delivered','Cancelled'] as $s):?><option <?=$o['status']==$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn">Save</button></form></td></tr><?php endforeach;?></table></section><?php include '_footer.php';?>
